                 <label for="q1-a">Python</label>
               </div>
               <div class="choice">
                 <input id="q1-b" type="checkbox" name="q1" value="html">
                 <label for="q1-b">HTML</label>
               </div>
               <div class="choice">
                 <input id="q1-c" type="checkbox" name="q1" value="java" data-correct="true">
                 <label for="q1-c">Java</label>
               </div>
               <div class="choice">
                 <input id="q1-d" type="checkbox" name="q1" value="css">
                 <label for="q1-d">CSS</label>
               </div>
