     const form = document.getElementById("quiz-form");
     const result = document.getElementById("quiz-result");
     const groups = Array.from(form.querySelectorAll("fieldset[data-question]"));

     function setGroupState(fieldset, hasError) {
       const helpId = fieldset.querySelector(".help-text")?.id;
       const error = fieldset.querySelector(".error-text");
       const describedBy = [];

       if (helpId) {
         describedBy.push(helpId);
       }

       if (hasError && error) {
         describedBy.push(error.id);
       }

       if (describedBy.length > 0) {
         fieldset.setAttribute("aria-describedby", describedBy.join(" "));
       } else {
         fieldset.removeAttribute("aria-describedby");
       }

       if (error) {
         error.hidden = !hasError;
       }

       fieldset.classList.toggle("is-invalid", hasError);
     }

     function scoreGroup(fieldset) {
       const inputs = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));
       const selectedValues = inputs.filter((input) => input.checked).map((input) => input.value).sort();
       const correctValues = inputs.filter((input) => input.dataset.correct === "true").map((input) => input.value).sort();

       return JSON.stringify(selectedValues) === JSON.stringify(correctValues);
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let firstInvalidInput = null;

       groups.forEach((fieldset) => {
         const checkedInputs = fieldset.querySelectorAll('input[type="checkbox"]:checked');
         const hasError = checkedInputs.length === 0;

         setGroupState(fieldset, hasError);

         if (hasError && !firstInvalidInput) {
           firstInvalidInput = fieldset.querySelector('input[type="checkbox"]');
         }
       });

       if (firstInvalidInput) {
         result.textContent = "Please answer all 3 questions before submitting.";
         firstInvalidInput.focus();
         return;
       }

       const score = groups.reduce((total, fieldset) => total + Number(scoreGroup(fieldset)), 0);
       const allCorrect = score === groups.length;

       result.textContent = allCorrect
         ? `Perfect score: ${score} out of ${groups.length}.`
         : `You scored ${score} out of ${groups.length}.`;
     });

     groups.forEach((fieldset) => {
       fieldset.addEventListener("change", () => {
         const checkedInputs = fieldset.querySelectorAll('input[type="checkbox"]:checked');

         if (checkedInputs.length > 0) {
           setGroupState(fieldset, false);
         }
       });
     });
   </script>
